S = []
S.append(dict(id='us-earnings', file='us-earnings-tracker.html', script='us-earnings-tracker.js', guide_file='us-stocks.html', chapter='us-stocks-metrics', chapter_label='美股財報章節', category='us', tag='財報與估值', icon='fa-file-invoice-dollar', kicker='02 US EQUITIES', title='美股財報成長與 EPS 驚喜分析儀', description='抓取美股公開財報與歷史行情，觀察 EPS、營收成長與財報窗口價格反應。', intro='選擇美股標的，讀取 Yahoo 公開行情與 SEC 公司申報資料，將財報數字和價格反應放在同一條時間軸。', result_title='EPS、營收與財報窗口反應', controls=field('美股代號', '<select id="us-earnings-symbol"><option>NVDA</option><option>AAPL</option><option>MSFT</option><option>TSLA</option><option>AMZN</option><option>GOOGL</option></select>') + '<span class="global-control-note">Yahoo chart + SEC XBRL；資料不足會明確提示</span>', hud='<div><span>最新收盤</span><strong id="us-earnings-price">—</strong><small id="us-earnings-date">—</small></div><div><span>近 1 年報酬</span><strong id="us-earnings-return">—</strong><small>價格序列</small></div><div><span>最新 EPS</span><strong id="us-earnings-eps">—</strong><small>SEC XBRL</small></div><div><span>營收 YoY</span><strong id="us-earnings-revenue">—</strong><small>季度比較</small></div><div><span>財報前後波動</span><strong id="us-earnings-reaction">—</strong><small>窗口估算</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">PRICE / EARNINGS WINDOW</span><h2>價格、EPS 與營收成長</h2></div><canvas id="us-earnings-chart" role="img" aria-label="美股價格與財報指標歷史圖"></canvas></div>', read_copy='<h3>EPS 與營收</h3><p>EPS 需確認單位、基本股數與一次性損益；營收成長則要區分年增與季增，不能把單季跳升直接外推成年率。</p><h3>財報窗口</h3><p>工具以 SEC 申報日期附近的公開價格序列估算窗口反應，遇到休市或申報日期缺失時會縮短樣本並顯示限制。</p>', guide_html='<div><h3>公開資料口徑</h3><p>SEC Company Facts 的 XBRL facts 以公司申報為準；Yahoo 歷史收盤用來建立價格時間軸。不同公司的 fiscal year、幣別與會計標籤可能不同，必須回看原始 filing。</p><h3>EPS surprise 的正確讀法</h3><p>若公開端點同時提供分析師預期，才可計算 surprise；否則工具只呈現已申報 EPS 與價格反應，不把缺失預期值偽造成驚喜百分比。</p><h3>實戰檢核</h3><p>先看營收是否與 EPS 同向，再檢查毛利率、庫存、現金流與管理層展望，最後才把財報窗口波動放進風險計畫。</p></div>'))
S.append(dict(id='us-sec-insider', file='us-sec-insider-flow.html', script='us-sec-insider-flow.js', guide_file='us-stocks.html', chapter='us-stocks-practice', chapter_label='美股實戰章節', category='us', tag='SEC 申報', icon='fa-user-shield', kicker='02 US EQUITIES', title='美股內部人持股與 SEC 申報流向儀', description='讀取 SEC 公開申報索引，整理 Form 4、13F 與公司 filings 的時間分布與可查證入口。', intro='選擇美股公司，檢查 SEC 公開提交紀錄、Form 4 內部人申報與 13F 相關 filing 時間軸。', result_title='SEC Form 4／13F 申報趨勢', controls=field('公司代號', '<select id="sec-insider-symbol"><option value="NVDA">NVDA · NVIDIA</option><option value="AAPL">AAPL · Apple</option><option value="MSFT">MSFT · Microsoft</option><option value="TSLA">TSLA · Tesla</option></select>') + '<span class="global-control-note">SEC data.sec.gov；瀏覽器若被 CORS 阻擋會顯示重試</span>', hud='<div><span>最近 filing</span><strong id="sec-insider-date">—</strong><small id="sec-insider-form">—</small></div><div><span>近 90 日 Form 4</span><strong id="sec-insider-form4">—</strong><small>申報筆數</small></div><div><span>近 365 日 13F</span><strong id="sec-insider-13f">—</strong><small>申報索引</small></div><div><span>最新 accession</span><strong id="sec-insider-accession">—</strong><small>可回 SEC 查證</small></div><div><span>資料狀態</span><strong id="sec-insider-quality">—</strong><small>不是持股推測</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">SEC FILING FLOW</span><h2>Form 4／13F 提交密度</h2></div><canvas id="sec-insider-chart" role="img" aria-label="SEC Form 4 與 13F 申報時間分布圖"></canvas></div>', read_copy='<h3>Form 4</h3><p>Form 4 是 insider transaction 申報索引；頁面呈現 filing 次數與日期，不把申報筆數當成買賣金額或方向。</p><h3>Form 13F</h3><p>13F 是機構投資經理人的季度持倉申報。工具先建立公開 filing 時間軸，實際持倉細節必須點回 SEC 原始文件。</p>', guide_html='<div><h3>SEC 公開資料</h3><p>SEC 的 submissions API 提供公司 filing history；XBRL company facts 提供可比較的標準化財務 facts。資料由監管機構公開發布，仍需遵守 SEC 的使用政策。</p><h3>為什麼不直接推測「主力買超」</h3><p>filing 次數沒有方向、價格與持股數量的完整資訊。專業做法是把 filing 作為研究入口，逐筆核對 form、transaction code、shares、price 與 ownership。</p><h3>研究流程</h3><p>先用日期篩選，再開啟 accession 文件確認交易欄位，最後與價格、財報與公司公告交叉核對。</p></div>'))
S.append(dict(id='etf-nav', file='etf-nav-premium-tracker.html', script='etf-nav-premium-tracker.js', guide_file='etf.html', chapter='etf-metrics', chapter_label='ETF 指標章節', category='etf', tag='淨值與費用', icon='fa-layer-group', kicker='03 ETF', title='ETF 淨值折溢價與費用率分析儀', description='比較 ETF 公開市場價格、調整後價格代理、折溢價與長期費用拖累。', intro='選擇台股或美股 ETF，從公開價格與調整後價格序列建立折溢價代理與長期費用觀察。', result_title='價格、NAV 代理與追蹤差異', controls=field('ETF 代號', '<select id="etf-nav-symbol"><option value="0050.TW">0050.TW · 元大台灣50</option><option value="0056.TW">0056.TW · 元大高股息</option><option value="00878.TW">00878.TW · 國泰永續高股息</option><option value="00919.TW">00919.TW · 群益台灣精選高息</option><option value="SPY">SPY · S&P 500</option><option value="QQQ">QQQ · Nasdaq 100</option></select>') + '<span class="global-control-note">NAV 採公開 adjusted-close 代理；正式 NAV 以基金公告為準</span>', hud='<div><span>最新市場價</span><strong id="etf-nav-price">—</strong><small id="etf-nav-date">—</small></div><div><span>NAV 代理價</span><strong id="etf-nav-proxy">—</strong><small>adjusted close</small></div><div><span>折溢價代理</span><strong id="etf-nav-premium">—</strong><small>價格／代理 NAV − 1</small></div><div><span>一年追蹤差</span><strong id="etf-nav-tracking">—</strong><small>價格 vs 代理</small></div><div><span>年度費用率</span><strong id="etf-nav-fee">—</strong><small>公開設定</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">ETF PRICE / NAV PROXY</span><h2>市場價與 NAV 代理序列</h2></div><canvas id="etf-nav-chart" role="img" aria-label="ETF 市場價格與 NAV 代理圖"></canvas></div>', read_copy='<h3>折溢價</h3><p>折溢價＝市場價格 ÷ NAV − 1。若使用 adjusted close，只能稱作 NAV 代理，不能取代基金每日公布的實際淨值。</p><h3>追蹤差異</h3><p>長期價格與調整後價格的累積差異，會同時包含費用、稅務、股利再投資、匯率與資料調整方法。</p>', guide_html='<div><h3>公開 NAV 與價格</h3><p>ETF 的正式 NAV 來自基金或投信公告；市場價格來自交易所成交。工具將 Yahoo adjusted close 作為跨市場可取得的代理序列，並在介面明確標示。</p><h3>費用率</h3><p>總費用率、經理費、保管費與交易摩擦不一定以同一口徑披露。比較時要閱讀公開說明書、月報與基金網站。</p><h3>實戰檢核</h3><p>先看折溢價是否由流動性或市場時段造成，再查公告 NAV、成交量、配息與匯率，不以單日偏離直接下結論。</p></div>'))
S.append(dict(id='etf-drip-backtest', file='etf-drip-backtester.html', script='etf-drip-backtester.js', guide_file='etf-dividend-drip.html', chapter='drip-practice', chapter_label='ETF DRIP 實戰章節', category='etf', tag='股息回測', icon='fa-coins', kicker='03 ETF', title='ETF 股息再投入 DRIP 回測儀', description='使用公開歷史價格與股利事件，回測股息再投入與現金領出的長期差異。', intro='選擇 ETF，載入公開股利事件與歷史價格，逐次模擬 DRIP 股數、現金股利與總資產。', result_title='股息再投入與現金領出路徑', controls=field('ETF 代號', '<select id="drip-symbol"><option>0050.TW</option><option>0056.TW</option><option>00878.TW</option><option>SPY</option><option>QQQ</option><option>VYM</option></select>') + '<span class="global-control-note">Yahoo chart events=div；配息事件缺失會顯示資料不足</span>', hud='<div><span>期初價格</span><strong id="drip-start">—</strong><small>公開收盤</small></div><div><span>最新價格</span><strong id="drip-price">—</strong><small id="drip-date">—</small></div><div><span>DRIP 終值</span><strong id="drip-reinvest">—</strong><small>股利再投入</small></div><div><span>現金領出終值</span><strong id="drip-cash">—</strong><small>價格＋累積現金</small></div><div><span>股利事件</span><strong id="drip-events">—</strong><small>公開事件筆數</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">TOTAL RETURN / CASH FLOW</span><h2>DRIP 與現金領出比較</h2></div><canvas id="drip-chart" role="img" aria-label="ETF 股息再投入與現金領出歷史圖"></canvas></div>', read_copy='<h3>DRIP 模擬</h3><p>每次除息以當日價格將現金股利換成零股，股數可為小數；這是數學回測，不代表券商實際零股執行、稅費與滑價。</p><h3>現金領出</h3><p>現金模式保留股數不變，將每次股利累積為現金。兩條線的差異反映再投資的時間與價格。</p>', guide_html='<div><h3>股利事件與還原權息</h3><p>工具以公開 chart events=div 事件建立現金流；adjusted close 另作交叉參考。若事件遺漏或公司有拆分，必須回看 ETF 公告與基金資料。</p><h3>不把回測當預測</h3><p>歷史配息、價格與稅務制度不會自動延續。DRIP 的價值在於把再投入假設攤開，讓使用者檢查股數、日期、成本與現金流。</p><h3>回測檢核</h3><p>比較不同起始日、配息月份、費用與稅務口徑，並把結果與基金官方還原權息資料交叉核對。</p></div>'))
S.append(dict(id='bond-curve', file='bond-yield-curve-tracker.html', script='bond-yield-curve-tracker.js', guide_file='bonds.html', chapter='bonds-metrics', chapter_label='債券殖利率章節', category='fixed', tag='殖利率曲線', icon='fa-chart-area', kicker='04 FIXED INCOME', title='美國公債殖利率曲線與倒掛預警儀', description='讀取 FRED 2Y、10Y、30Y 殖利率與 10Y-2Y 利差，標記倒掛區段。', intro='載入聯準會 FRED 公開序列，將短、中、長天期殖利率與期限利差放在同一張互動圖。', result_title='殖利率曲線與 10Y−2Y 利差', controls='<span class="global-control-note">FRED DGS2／DGS10／DGS30／T10Y2Y · 公開日資料</span>', hud='<div><span>最新 2Y</span><strong id="bond-2y">—</strong><small>FRED DGS2</small></div><div><span>最新 10Y</span><strong id="bond-10y">—</strong><small>FRED DGS10</small></div><div><span>最新 30Y</span><strong id="bond-30y">—</strong><small>FRED DGS30</small></div><div><span>10Y−2Y</span><strong id="bond-spread">—</strong><small id="bond-regime">—</small></div><div><span>倒掛日數</span><strong id="bond-inverted-days">—</strong><small>查詢窗口</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">FRED YIELD CURVE</span><h2>2Y、10Y、30Y 與 10Y−2Y 利差</h2></div><canvas id="bond-curve-chart" role="img" aria-label="美國公債殖利率曲線與利差圖"></canvas></div>', read_copy='<h3>期限結構</h3><p>曲線反映不同到期日的殖利率，不是直接的報酬率預測。2Y、10Y、30Y 應連同通膨、財政與信用條件閱讀。</p><h3>倒掛</h3><p>10Y−2Y 小於零代表該利差倒掛；它是景氣風險訊號，不是精準擇時器。</p>', guide_html='<div><h3>FRED 序列</h3><p>工具讀取 FRED 的 DGS2、DGS10、DGS30 與 T10Y2Y 公開觀測值。FRED 觀測可能有修訂，頁面會保留資料日期。</p><h3>利差計算</h3><p>若同日 T10Y2Y 缺值，工具會以 10Y−2Y 重新計算；這可協助理解公式，但不覆蓋官方序列的定義。</p><h3>研判流程</h3><p>先確認曲線形狀，再觀察倒掛持續時間與實質利率、信用利差、就業和通膨資料，避免只用一條線做結論。</p></div>'))
S.append(dict(id='fund-sharpe', file='fund-sharpe-drawdown-analyzer.html', script='fund-sharpe-drawdown-analyzer.js', guide_file='funds.html', chapter='funds-metrics', chapter_label='基金風險指標章節', category='funds', tag='Sharpe／MDD', icon='fa-chart-line', kicker='05 FUNDS / PORTFOLIO', title='基金與投資組合 Sharpe、Sortino、MDD 分析儀', description='使用公開基金或 ETF 歷史價格計算年化報酬、波動度、Sharpe、Sortino 與最大回撤。', intro='選擇可由 Yahoo 公開行情取得的基金／ETF 代號，以真實歷史價格建立風險調整後績效與水下回撤圖。', result_title='報酬、風險與水下回撤', controls=field('基金／ETF 代號', '<input id="fund-symbol" value="VTI" maxlength="16" autocomplete="off">') + '<span class="global-control-note">可輸入 VTI、QQQ、SPY、BND 等公開行情代號</span>', hud='<div><span>年化報酬</span><strong id="fund-return">—</strong><small>價格報酬</small></div><div><span>年化波動</span><strong id="fund-volatility">—</strong><small>日報酬年化</small></div><div><span>Sharpe</span><strong id="fund-sharpe-value">—</strong><small>無風險率採 FRED</small></div><div><span>Sortino</span><strong id="fund-sortino">—</strong><small>下行波動</small></div><div><span>最大回撤</span><strong id="fund-mdd">—</strong><small id="fund-mdd-date">—</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">RISK-ADJUSTED PERFORMANCE</span><h2>累積報酬與水下回撤</h2></div><canvas id="fund-sharpe-chart" role="img" aria-label="基金累積報酬與最大回撤圖"></canvas></div>', read_copy='<h3>Sharpe</h3><p>Sharpe＝（年化報酬−無風險率）÷年化波動；工具使用公開短天期殖利率或 FRED 序列作為近似無風險率。</p><h3>Sortino 與 MDD</h3><p>Sortino 只懲罰低於零的日報酬；MDD 是從歷史高點到後續低點的最大跌幅，兩者要連同投資期間與現金流閱讀。</p>', guide_html='<div><h3>價格資料口徑</h3><p>基金與 ETF 的公開行情可能不含完整配息、費用與申購贖回成本。工具先以價格序列做透明比較，不把它稱為完整投資人報酬。</p><h3>風險調整績效</h3><p>Sharpe 高不等於未來一定較好；比較時要保持期間、頻率、基準與缺值處理一致。</p><h3>水下回撤</h3><p>回撤圖可協助檢查持有體驗，但不能取代流動性、基金規模、經理費與投資策略的閱讀。</p></div>'))
S.append(dict(id='forex-carry', file='forex-interest-carry-calc.html', script='forex-interest-carry-calc.js', guide_file='forex.html', chapter='forex-carry', chapter_label='外匯利差交易章節', category='forex', tag='Carry／Swap', icon='fa-money-bill-transfer', kicker='06 FX / CURRENCIES', title='主要貨幣對利差交易與匯率波動儀', description='讀取 USDJPY、EURUSD、GBPUSD 公開匯率與 FRED 利率序列，觀察利差與匯率波動。', intro='選擇貨幣對，載入公開匯率與短期利率資料，將 carry proxy、匯率走勢與波動放在一起檢查。', result_title='匯率、利差代理與波動', controls=field('貨幣對', '<select id="forex-pair"><option value="USDJPY=X">USDJPY</option><option value="EURUSD=X">EURUSD</option><option value="GBPUSD=X">GBPUSD</option></select>') + '<span class="global-control-note">Yahoo FX + FRED 利率序列；利差為政策利率代理</span>', hud='<div><span>最新匯率</span><strong id="forex-price">—</strong><small id="forex-date">—</small></div><div><span>30 日波動</span><strong id="forex-vol">—</strong><small>年化代理</small></div><div><span>利差代理</span><strong id="forex-spread">—</strong><small>百分點</small></div><div><span>Carry proxy</span><strong id="forex-carry">—</strong><small>未含 swap 報價</small></div><div><span>最大日變動</span><strong id="forex-shock">—</strong><small>查詢窗口</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">FX / RATE DIFFERENTIAL</span><h2>匯率與利差代理雙軸圖</h2></div><canvas id="forex-carry-chart" role="img" aria-label="貨幣對匯率與利差代理圖"></canvas></div>', read_copy='<h3>利差交易</h3><p>Carry 不是只看兩國名目利率；還要納入遠期點、swap 報價、匯率波動與平倉風險。</p><h3>資料代理</h3><p>工具以 FRED 的公開短期利率序列近似利率差，沒有把它當成券商實際 overnight swap。</p>', guide_html='<div><h3>基準貨幣與報價貨幣</h3><p>USDJPY 表示 1 美元兌多少日圓；EURUSD 則表示 1 歐元兌多少美元。方向不同會影響報酬與波動解讀。</p><h3>Pip 與波動</h3><p>匯率變動要依貨幣對小數位換算 pip；工具使用日報酬與年化波動代理，實務仍要查看交易商報價與點差。</p><h3>Carry 風控</h3><p>利差擴大不代表匯率一定有利；週末跳空、央行意外與槓桿平倉可能一次抹去多期 carry。</p></div>'))
S.append(dict(id='commodity-ratio', file='commodity-gold-oil-ratio.html', script='commodity-gold-oil-ratio.js', guide_file='commodities.html', chapter='commodities-metrics', chapter_label='商品比率章節', category='commodities', tag='金銀比／金油比', icon='fa-gem', kicker='07 COMMODITIES', title='金銀比、金油比與通膨週期監控儀', description='抓取 GC、SI、CL 公開期貨價格，繪製金銀比、金油比與歷史極端值通道。', intro='載入黃金、白銀與原油公開期貨行情，以比率、均值與標準差通道觀察商品週期結構。', result_title='商品比率與極端值通道', controls='<span class="global-control-note">Yahoo GC=F／SI=F／CL=F · 2 年日線</span>', hud='<div><span>黃金</span><strong id="commodity-gold">—</strong><small>GC=F</small></div><div><span>白銀</span><strong id="commodity-silver">—</strong><small>SI=F</small></div><div><span>原油</span><strong id="commodity-oil">—</strong><small>CL=F</small></div><div><span>金銀比</span><strong id="commodity-gs">—</strong><small>gold / silver</small></div><div><span>金油比 Z</span><strong id="commodity-go">—</strong><small>2 年標準化</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">RATIO / Z-SCORE</span><h2>金銀比與金油比歷史通道</h2></div><canvas id="commodity-ratio-chart" role="img" aria-label="金銀比與金油比歷史圖"></canvas></div>', read_copy='<h3>金銀比</h3><p>金銀比＝黃金價格 ÷ 白銀價格，常被用來比較避險與工業需求的相對定價，但不是單一買賣訊號。</p><h3>金油比</h3><p>金油比會同時受到黃金避險需求、能源供需與美元影響；Z 分數只是相對歷史位置。</p>', guide_html='<div><h3>比率的用途</h3><p>比率能把不同單位價格轉成相對尺度，適合做週期比較；它不會告訴你每個商品的絕對風險。</p><h3>通道與極端值</h3><p>工具以移動平均與標準差建立視覺通道；極端值可能持續很久，不能直接視為均值回歸保證。</p><h3>實戰檢核</h3><p>將比率與美元、實質利率、庫存、期限結構與波動一起看，並確認期貨換月與資料連續性。</p></div>'))
S.append(dict(id='futures-basis', file='futures-basis-term-structure.html', script='futures-basis-term-structure.js', guide_file='futures.html', chapter='futures-metrics', chapter_label='期貨期限結構章節', category='futures', tag='Basis／轉倉', icon='fa-arrows-left-right-to-line', kicker='08 FUTURES', title='期現貨實質價差與期限結構儀', description='使用公開期貨與現貨指數行情，計算 NQ／Nasdaq、ES／S&P 的 basis 與期限結構代理。', intro='選擇美國指數期貨組合，載入期貨與現貨指數日線，觀察正逆價差、年化 basis 與結算收斂。', result_title='期貨、現貨與 Basis 走勢', controls=field('期貨組合', '<select id="futures-basis-symbol"><option value="NQ=F|^IXIC|Nasdaq-100">NQ／Nasdaq-100</option><option value="ES=F|^GSPC|S&P 500">ES／S&P 500</option></select>') + '<span class="global-control-note">Yahoo futures + spot index；台指期公開資料依端點可得性顯示</span>', hud='<div><span>期貨最新</span><strong id="futures-price">—</strong><small id="futures-date">—</small></div><div><span>現貨指數</span><strong id="futures-spot">—</strong><small>spot proxy</small></div><div><span>Basis</span><strong id="futures-basis">—</strong><small>期貨／現貨 − 1</small></div><div><span>年化 Basis</span><strong id="futures-annualized">—</strong><small>近似 30 日</small></div><div><span>收斂觀察</span><strong id="futures-convergence">—</strong><small>價格差趨勢</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">FUTURES / SPOT BASIS</span><h2>期貨、現貨與價差代理</h2></div><canvas id="futures-basis-chart" role="img" aria-label="指數期貨與現貨 basis 歷史圖"></canvas></div>', read_copy='<h3>Basis</h3><p>Basis ＝期貨價格 ÷ 現貨價格 − 1；正值可能反映持有成本、股息、資金與供需，不能只解讀成看多。</p><h3>期限結構</h3><p>真正期限結構需要多個到期月份；本工具以最接近公開連續期貨與現貨的價差作為教育型代理，換月時要特別小心。</p>', guide_html='<div><h3>正逆價差</h3><p>期貨高於現貨稱正價差，低於現貨稱逆價差；利率、股息、庫存與便利收益會共同影響價格。</p><h3>轉倉成本</h3><p>連續期貨資料可能在換月時跳動。計算轉倉報酬前，必須檢查合約月份、乘數、保證金與交易時段。</p><h3>收斂</h3><p>到期時期貨理論上接近現貨，但實務會受結算規則、基差風險與資料時間差影響。</p></div>'))
S.append(dict(id='options-iv', file='options-implied-volatility-rank.html', script='options-implied-volatility-rank.js', guide_file='options.html', chapter='options-metrics', chapter_label='選擇權波動率章節', category='options', tag='IV Rank／PCR', icon='fa-wave-square', kicker='09 OPTIONS / VOLATILITY', title='隱含波動率 IV Rank 與 Put/Call Ratio 儀', description='讀取公開選擇權鏈（若端點可用），比較標的歷史波動率、IV、IV Rank 與 Put/Call Ratio。', intro='輸入可取得公開選擇權鏈的美股標的，工具同時計算歷史波動率與公開 options chain 的 IV／未平倉量結構。', result_title='HV、IV Rank 與 Put／Call Ratio', controls=field('標的代號', '<input id="options-symbol" value="SPY" maxlength="12" autocomplete="off">') + '<span class="global-control-note">Yahoo options chain；端點拒絕時顯示 HV 與明確錯誤，不補假 IV</span>', hud='<div><span>歷史波動 HV</span><strong id="options-hv">—</strong><small>20 日年化</small></div><div><span>隱含波動 IV</span><strong id="options-iv-value">—</strong><small>ATM 代理</small></div><div><span>IV Rank</span><strong id="options-ivr">—</strong><small>歷史分位</small></div><div><span>Put／Call OI</span><strong id="options-pcr">—</strong><small>未平倉量</small></div><div><span>資料狀態</span><strong id="options-quality">—</strong><small>公開鏈可得性</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">VOLATILITY / SKEW</span><h2>HV、IV 與 Put／Call 結構</h2></div><canvas id="options-iv-chart" role="img" aria-label="選擇權歷史波動與隱含波動圖"></canvas></div>', read_copy='<h3>HV 與 IV</h3><p>HV 由標的歷史報酬計算；IV 是市場對未來波動的定價。兩者期限、履約價與流動性不同，不能直接當成同一數字。</p><h3>IV Rank</h3><p>IV Rank 需要一段歷史 IV 序列；若公開鏈只提供當下 chain，工具會把 rank 標示為不可得，不用 HV 偽裝成 IV Rank。</p>', guide_html='<div><h3>公開 options chain</h3><p>選擇權資料包含到期日、履約價、買賣價、IV 與未平倉量；不同端點可能延遲、缺漏或限制請求。工具會標示 chain 是否成功。</p><h3>Put／Call Ratio</h3><p>PCR 可用成交量或未平倉量定義；本頁採未平倉量口徑，並在圖表與結果中明示。</p><h3>波動率研判</h3><p>高 IV 可能代表事件風險，也可能包含流動性溢價。實戰要將期限、delta、價差寬度、保證金與希臘字母一併檢查。</p></div>'))
S.append(dict(id='crypto-funding', file='crypto-funding-rate-liquidations.html', script='crypto-funding-rate-liquidations.js', guide_file='crypto.html', chapter='crypto-metrics', chapter_label='虛擬貨幣衍生品章節', category='crypto', tag='Funding／清算', icon='fa-bitcoin', kicker='10 CRYPTO', title='永續合約資金費率與多空清算儀', description='對接 Binance 公開端點，抓取 BTC、ETH、SOL 資金費率與多空比率，呈現清算風險代理。', intro='選擇 Binance 永續合約，載入 8 小時資金費率、標記價格與公開多空比率，檢查槓桿擁擠程度。', result_title='Funding、Long／Short 與清算壓力代理', controls=field('永續合約', '<select id="crypto-symbol"><option>BTCUSDT</option><option>ETHUSDT</option><option>SOLUSDT</option></select>') + '<span class="global-control-note">Binance Futures public REST；公開端點不等同你在交易所的實際清算紀錄</span>', hud='<div><span>標記價格</span><strong id="crypto-price">—</strong><small id="crypto-date">—</small></div><div><span>最新 Funding</span><strong id="crypto-funding-rate">—</strong><small>8 小時</small></div><div><span>Funding 平均</span><strong id="crypto-funding-avg">—</strong><small>查詢窗口</small></div><div><span>多空帳戶比</span><strong id="crypto-long-short">—</strong><small>global ratio</small></div><div><span>清算壓力</span><strong id="crypto-pressure">—</strong><small>Funding／多空代理</small></div><div><span>多方清算</span><strong id="crypto-long-liquidation">—</strong><small>近 100 筆</small></div><div><span>空方清算</span><strong id="crypto-short-liquidation">—</strong><small>近 100 筆</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">FUNDING / POSITIONING</span><h2>8 小時 Funding 與多空帳戶比</h2></div><canvas id="crypto-funding-chart" role="img" aria-label="加密貨幣資金費率與多空比圖"></canvas></div>', read_copy='<h3>Funding rate</h3><p>正 funding 通常代表多方支付空方；實際結算、上下限與計算方式要以交易所合約規則為準。</p><h3>多空比與清算</h3><p>多空帳戶比不是名義倉位，也不是清算金額。工具將它和 funding 合併成壓力代理，避免把缺少清算流水的資料寫成精確清算量。</p>', guide_html='<div><h3>公開合約資料</h3><p>Binance Futures public REST 可取得 funding history 與 global long／short account ratio。端點可能受地區、速率與服務狀態影響。</p><h3>擁擠交易</h3><p>Funding 高、方向比失衡時，市場對反向波動更敏感；但 funding 也可能在趨勢行情中長時間偏正或偏負。</p><h3>風險檢核</h3><p>永續合約還有槓桿、標記價格、強平、保證金與保險基金風險。任何代理值都不能取代你的倉位與保證金監控。</p></div>'))
S.append(dict(id='real-estate-roi', file='real-estate-roi-cap-rate.html', script='real-estate-roi-cap-rate.js', guide_file='real-estate.html', chapter='real-estate-metrics', chapter_label='房地產收益率章節', category='real-estate', tag='Cap Rate／房貸', icon='fa-house', kicker='11 REAL ESTATE', title='不動產 Cap Rate 與房貸壓力測試儀', description='以真實物件成交價、租金、費用與貸款條件計算 Cap Rate、NOI、DSCR 與升息壓力。', intro='輸入你正在研究的真實物件與貸款條件；工具以透明公式計算租金收益與利率上升後的現金流壓力。', result_title='NOI、Cap Rate、DSCR 與升息壓力', controls=field('物件總價', '<input id="re-price" type="number" value="12000000" min="1" step="10000">') + field('月租金', '<input id="re-rent" type="number" value="32000" min="0" step="500">') + field('年費用率', '<input id="re-expense" type="number" value="20" min="0" max="100" step="1">') + field('貸款成數', '<input id="re-ltv" type="number" value="70" min="0" max="100" step="1">') + field('年利率', '<input id="re-rate" type="number" value="2.2" min="0" step="0.1">') + field('貸款年限', '<input id="re-years" type="number" value="30" min="1" step="1">') + '<span class="global-control-note">請輸入實際物件與銀行條件；此頁為公開公式計算，不是行情假數字</span>', hud='<div><span>毛租金殖利率</span><strong id="re-gross-yield">—</strong><small>年租金／總價</small></div><div><span>NOI</span><strong id="re-noi">—</strong><small>扣費用後</small></div><div><span>Cap Rate</span><strong id="re-cap-rate">—</strong><small>NOI／總價</small></div><div><span>月供款</span><strong id="re-payment">—</strong><small>本息攤還</small></div><div><span>DSCR</span><strong id="re-dscr">—</strong><small>NOI／年債務服務</small></div><div><span>+1% 升息後 DSCR</span><strong id="re-stress">—</strong><small>壓力測試</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">CASH FLOW / RATE STRESS</span><h2>貸款餘額、利息與本金路徑</h2></div><canvas id="re-chart" role="img" aria-label="房貸本金利息與餘額壓力測試圖"></canvas></div>', read_copy='<h3>Cap Rate</h3><p>Cap Rate＝NOI ÷ 物件總價；NOI 要先扣除空置、管理、維修、稅費與保險等營運費用。</p><h3>DSCR</h3><p>DSCR＝NOI ÷ 年債務服務。小於 1 代表物業營運收入不足以覆蓋貸款本息，但仍要考慮稅務與一次性支出。</p>', guide_html='<div><h3>資料輸入原則</h3><p>房地產條件高度在地化；工具要求使用者輸入實際成交價、租賃契約、費用與銀行報價，不用虛構即時房價或租金資料。</p><h3>本息攤還</h3><p>月付額使用固定利率攤還公式；升息壓力測試把年利率上調 1 個百分點，再比較付款、DSCR 與剩餘現金流。</p><h3>風險檢核</h3><p>空置、修繕、稅費、鑑價不足、寬限期結束與利率重定價都可能使紙上收益失真，應建立保守、基準與壓力三組真實條件。</p></div>'))
S.append(dict(id='macro-liquidity', file='macro-liquidity-cpi-tracker.html', script='macro-liquidity-cpi-tracker.js', guide_file='macro-economics.html', chapter='macro-economics-metrics', chapter_label='總經流動性章節', category='macro', tag='M2／CPI／流動性', icon='fa-earth-americas', kicker='12 MACROECONOMICS', title='全球流動性、M2 與 CPI 通膨指標儀', description='讀取 FRED Fed 資產負債表、M2、CPI 與 SPY 公開序列，建立流動性與風險資產比較圖。', intro='載入 FRED WALCL、M2SL、CPIAUCSL 與公開 SPY 價格，觀察標準化流動性、通膨與市場路徑。', result_title='Fed 資產、M2、CPI 與 S&P 500', controls='<span class="global-control-note">FRED WALCL／M2SL／CPIAUCSL + Yahoo SPY；頻率差異會保留</span>', hud='<div><span>Fed 資產</span><strong id="macro-walcl">—</strong><small>WALCL</small></div><div><span>M2</span><strong id="macro-m2">—</strong><small>M2SL</small></div><div><span>CPI YoY</span><strong id="macro-cpi">—</strong><small>CPIAUCSL</small></div><div><span>SPY 1 年</span><strong id="macro-spy">—</strong><small>市場價格</small></div><div><span>流動性／CPI</span><strong id="macro-liquidity-score">—</strong><small>標準化相對路徑</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">LIQUIDITY / INFLATION / RISK ASSET</span><h2>公開宏觀序列標準化比較</h2></div><canvas id="macro-chart" role="img" aria-label="全球流動性、M2、CPI 與 SPY 比較圖"></canvas></div>', read_copy='<h3>流動性</h3><p>央行資產與 M2 的方向可協助理解金融條件，但不等同於立即流入股市的資金。</p><h3>CPI</h3><p>CPI 是價格水準，不是單期通膨率；工具以同比變化計算 CPI YoY，並保留原始發布頻率。</p>', guide_html='<div><h3>頻率對齊</h3><p>WALCL、M2SL、CPIAUCSL 與 SPY 的頻率不同。工具以各序列日期向前填入最近觀測，並在資料狀態中提示這是比較圖，不是同頻因果估計。</p><h3>標準化</h3><p>把各序列起點設為 100 只能比較相對路徑，不能比較單位大小。若基期不同，視覺訊號也會改變。</p><h3>宏觀研判</h3><p>把流動性與 CPI 和實質利率、信用利差、就業、盈利與估值一起看，避免單一總經指標決定交易。</p></div>'))
S.append(dict(id='trade-risk-kelly', file='trade-risk-kelly-criterion.html', script='trade-risk-kelly-criterion.js', guide_file='trading-strategy.html', chapter='position-sizing', chapter_label='部位管理章節', category='strategy', tag='Kelly／R:R', icon='fa-shield-halved', kicker='13 TRADING EXECUTION', title='Kelly 部位管理、R:R 與破產機率儀', description='以實際交易計畫的勝率、盈虧比、停損與資金計算 Kelly、下單口數與資金成長路徑。', intro='輸入你交易紀錄或策略回測得到的勝率與盈虧比，透明計算 Kelly 參考、風險股數與固定種子蒙地卡羅路徑。', result_title='Kelly、下單口數與資金成長模擬', controls=field('帳戶資金', '<input id="risk-capital" type="number" value="500000" min="1" step="1000">') + field('進場價', '<input id="risk-entry" type="number" value="100" min="0.0001" step="0.01">') + field('停損價', '<input id="risk-stop" type="number" value="95" min="0.0001" step="0.01">') + field('勝率 %', '<input id="risk-win" type="number" value="45" min="0" max="100" step="0.1">') + field('平均獲利／平均虧損', '<input id="risk-payoff" type="number" value="2" min="0.01" step="0.1">') + field('單筆風險 %', '<input id="risk-budget" type="number" value="1" min="0.01" max="100" step="0.1">') + '<span class="global-control-note">參數應來自你的真實紀錄；蒙地卡羅為可重現數學路徑，非行情預測</span>', hud='<div><span>R:R</span><strong id="risk-rr">—</strong><small>獲利／風險</small></div><div><span>Kelly fraction</span><strong id="risk-kelly">—</strong><small>未調整參考</small></div><div><span>半 Kelly</span><strong id="risk-half-kelly">—</strong><small>保守參考</small></div><div><span>建議股數</span><strong id="risk-qty">—</strong><small>風險預算／停損距離</small></div><div><span>跌破半數頻率</span><strong id="risk-ruin">—</strong><small>固定種子模擬</small></div>', charts='<div class="global-chart-box"><div class="global-chart-title"><span class="section-kicker">KELLY / MONTE CARLO</span><h2>資金成長與回撤路徑</h2></div><canvas id="risk-chart" role="img" aria-label="Kelly 資金成長蒙地卡羅圖"></canvas></div>', read_copy='<h3>Kelly 公式</h3><p>f*＝(bp−q)÷b，其中 b 是平均獲利／平均虧損、p 是勝率、q＝1−p。Kelly 是理論上限，不代表應全額使用。</p><h3>下單口數</h3><p>股數＝帳戶資金 × 單筆風險比例 ÷ 每股停損距離；結果要再受流動性、跳空、最小單位與可用保證金約束。</p>', guide_html='<div><h3>R:R 與期望值</h3><p>R:R 只是單筆結構；期望值還需要勝率、虧損尾部、成本與滑價。工具將公式拆開，避免把高 R:R 直接等同高勝率。</p><h3>破產與回撤</h3><p>模擬使用固定種子、固定交易次數與二項勝負路徑，展示參數組合可能形成的回撤，不是未來報酬分布的保證。</p><h3>執行檢核</h3><p>用真實交易紀錄估計勝率與盈虧比，採用半 Kelly 或更低風險，並把連續虧損、跳空與交易成本納入壓力測試。</p></div>'))

